-- Function: public.fn_get_board_teacher_children_care_status
-- Backup generated on 2026-10-25 20:33:04

CREATE OR REPLACE FUNCTION public.fn_get_board_teacher_children_care_status(p_tenant_id uuid, p_org_id uuid, p_date date, p_start_of_day timestamp with time zone, p_end_of_day timestamp with time zone, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(child_id uuid, full_name text, photo_url text, is_checked_in boolean, arrival_time time without time zone, care_events_count integer, last_recorded_care_type character varying, last_recorded_time timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          c.id AS child_id,         c.first_name || ' ' || c.last_name AS full_name,         c.photo_url AS photo_url,         true AS is_checked_in,         ca.arrival_time AS arrival_time,         COALESCE((             SELECT COUNT(1)::int FROM child_care_events cce              WHERE cce.child_id = c.id AND cce.tenant_id = p_tenant_id                AND cce.event_time >= p_start_of_day AND cce.event_time <= p_end_of_day         ), 0) AS care_events_count,         (             SELECT cce.event_type FROM child_care_events cce             WHERE cce.child_id = c.id AND cce.tenant_id = p_tenant_id                AND cce.event_time >= p_start_of_day AND cce.event_time <= p_end_of_day             ORDER BY cce.event_time DESC LIMIT 1         ) AS last_recorded_care_type,         (             SELECT cce.event_time FROM child_care_events cce             WHERE cce.child_id = c.id AND cce.tenant_id = p_tenant_id                AND cce.event_time >= p_start_of_day AND cce.event_time <= p_end_of_day             ORDER BY cce.event_time DESC LIMIT 1         ) AS last_recorded_time     FROM children c     JOIN child_attendance ca ON c.id = ca.child_id AND ca.attendance_date = p_date AND ca.status IN ('Present', 'Late')     JOIN classrooms cl ON c.classroom_id = cl.id     JOIN branches b ON cl.branch_id = b.id     WHERE c.tenant_id = p_tenant_id       AND b.organization_id = p_org_id       AND (p_branch_id IS NULL OR cl.branch_id = p_branch_id)       AND (p_classroom_id IS NULL OR cl.id = p_classroom_id); $function$ ;
